"use strict";
let kept = null;
function describe(xs) {
  return `isArray=${Array.isArray(xs)} length=${xs.length} first=${xs[0]} last=${xs[xs.length - 1]}`;
}
function sum(xs) {
  return xs.reduce((a, b) => a + b, 0);
}
function maxVersion(versions) {
  return versions.map((v) => v.split(".").map(Number)).sort((a, b) => b[0] - a[0] || b[1] - a[1])[0].join(".");
}
function append(xs, ...items) {
  xs.push(...items);
  return xs.length;
}
function bump(xs) {
  for (let i = 0; i < xs.length; i++) xs[i] *= 10;
}
function truncate(xs, n) {
  xs.length = n;
}
function entries(pairs) {
  const out = [];
  for (const [name, info] of pairs) out.push(`${name}:${info.size}`);
  return out.join(" ");
}
function json(x) {
  return JSON.stringify(x);
}
function keep(xs) {
  kept = xs;
}
function isKept(xs) {
  return kept === xs;
}
function keys(xs) {
  return Object.keys(xs).join(",") + " " + ("1" in xs) + " " + (99 in xs);
}
function show(x) {
  return require("node:util").inspect(x);
}
module.exports = { show, describe, sum, maxVersion, append, bump, truncate, entries, json, keep, isKept, keys };
